S="C:/Users/dasbl/AppData/Local/Temp/claude/D--the-synaptic-sea-2d/a5c30614-4e6e-4b6b-a781-54ec94879f80/scratchpad"; cat > "$S/wd.py" <<'EOF'
import sys,difflib,re
lines=open(sys.argv[1],encoding='utf-8').read().split('\n')
i=0
minus=[];plus=[]
def flush():
    global minus,plus
    if minus or plus:
        a=' '.join(m[1:] for m in minus); b=' '.join(p[1:] for p in plus)
        ta=re.findall(r'\S+|\s+',a); tb=re.findall(r'\S+|\s+',b)
        sm=difflib.SequenceMatcher(None,ta,tb,autojunk=False)
        out=[]
        for op,i1,i2,j1,j2 in sm.get_opcodes():
            if op=='equal':
                t=''.join(ta[i1:i2])
                out.append(t if len(t)<160 else t[:70]+' ... '+t[-70:])
            else:
                if i2>i1: out.append('[-'+''.join(ta[i1:i2])+'-]')
                if j2>j1: out.append('{+'+''.join(tb[j1:j2])+'+}')
        print(''.join(out)); print('-----')
    minus=[];plus=[]
for l in lines:
    if l.startswith('@@'):
        flush(); print('\n'+l[:80])
    elif l.startswith('---') or l.startswith('+++') or l.startswith('diff') or l.startswith('index'): continue
    elif l.startswith('-'): minus.append(l)
    elif l.startswith('+'): plus.append(l)
    else: flush()
flush()
EOF
python "$S/wd.py" "$S/lsg.diff" > "$S/lsg.wd.txt"; wc -c "$S/lsg.wd.txt"

